from abc import ABC, abstractmethod

class Funcionario(ABC):
    def __init__(self, nome, salario_base):
        self.nome = nome
        self.salario_base = salario_base

    @abstractmethod
    def calcular_salario(self):
        pass

    def contracheque(self):
        return f"{self.nome} ({type(self).__name__}): R$ {self.calcular_salario():.2f}"


class Desenvolvedor(Funcionario):
    def calcular_salario(self):
        return self.salario_base


class Gerente(Funcionario):
    def __init__(self, nome, salario_base, bonus):
        super().__init__(nome, salario_base)
        self.bonus = bonus

    def calcular_salario(self):
        return self.salario_base + self.bonus


class Vendedor(Funcionario):
    def __init__(self, nome, salario_base, vendas, taxa=0.05):
        super().__init__(nome, salario_base)
        self.vendas = vendas
        self.taxa = taxa

    def calcular_salario(self):
        return self.salario_base + self.vendas * self.taxa


class Estagiario(Desenvolvedor):
    def calcular_salario(self):
        return super().calcular_salario() * 0.5


equipe = [
    Desenvolvedor("Ana", 6000),
    Gerente("Bruno", 8000, 2000),
    Vendedor("Carla", 2500, 40000),
    Estagiario("Davi", 3000),
]

total = 0
for funcionario in equipe:
    print(funcionario.contracheque())
    total += funcionario.calcular_salario()
print(f"Folha total: R$ {total:.2f}")

