class Conta:
    def __init__(self, titular, saldo=0):
        self.titular = titular
        self.saldo = saldo

    def sacar(self, valor):
        if valor > self.saldo:
            print("Saldo insuficiente.")
            return False
        self.saldo -= valor
        return True

class ContaCorrente(Conta):
    TAXA = 2.0

    def sacar(self, valor):
        return super().sacar(valor + ContaCorrente.TAXA)

c1 = Conta("Ana", 100)
