from abc import ABC, abstractmethod

class Forma(ABC):
    @abstractmethod
    def area(self):
        pass

    @abstractmethod
    def perimetro(self):
        pass

class Quadrado(Forma):
    def __init__(self, lado):
        self.lado = lado

    def area(self):
        return self.lado ** 2

    def perimetro(self):
        return 4 * self.lado

class Triangulo(Forma):
    def __init__(self, a, b, c):
        self.a, self.b, self.c = a, b, c

    def perimetro(self):
        return self.a + self.b + self.c

    def area(self):
        s = self.perimetro() / 2
        return (s * (s - self.a) * (s - self.b) * (s - self.c)) ** 0.5

for forma in [Quadrado(4), Triangulo(3, 4, 5)]:
    print(f"{type(forma).__name__}: área {forma.area():.1f}, perímetro {forma.perimetro():.1f}")
# Quadrado: área 16.0, perímetro 16.0
# Triangulo: área 6.0, perímetro 12.0

