class Personagem:
    def __init__(self, nome, vida=100):
        self.nome = nome
        self.vida = vida

    def atacar(self):
        return 10

    def receber_dano(self, dano):
        self.vida = max(0, self.vida - dano)

class Guerreiro(Personagem):
    def atacar(self):
        return super().atacar() * 2

class Mago(Personagem):
    def __init__(self, nome, mana=50):
        super().__init__(nome, vida=80)
        self.mana = mana

    def atacar(self):
        if self.mana >= 10:
            self.mana -= 10
            return 25
        return super().atacar()

g = Guerreiro("Thor")
m = Mago("Merlin", mana=15)
for rodada in range(1, 3):
    m.receber_dano(g.atacar())
    g.receber_dano(m.atacar())
    print(f"Rodada {rodada}: {g.nome} {g.vida} | {m.nome} {m.vida} (mana {m.mana})")
# Rodada 1: Thor 75 | Merlin 60 (mana 5)
# Rodada 2: Thor 65 | Merlin 40 (mana 5)

